export const localCastQueueSource = "(() => {\nfunction duration(seconds) { return Math.floor(seconds / 60) + ':' + String(Math.floor(seconds % 60)).padStart(2, '0'); }\nfunction createLocalCastQueueView(list, status, count, labels, select, fallbackCover, resolveCover) {\n    let pending = [];\n    let loading = 0;\n    const sources = new WeakMap();\n    function pump() {\n        while (loading < 3 && pending.length > 0) {\n            const item = pending.shift();\n            loading++;\n            void resolveCover(item.url).then(url => {\n                if (item.image.isConnected)\n                    item.image.src = url || fallbackCover;\n            }).catch(() => { }).finally(() => { loading--; pump(); });\n        }\n    }\n    const observer = new IntersectionObserver(entries => {\n        entries.forEach(entry => {\n            if (!entry.isIntersecting)\n                return;\n            const url = sources.get(entry.target);\n            observer.unobserve(entry.target);\n            pending.push({ image: entry.target, url });\n        });\n        pump();\n    }, { root: list, rootMargin: '120px' });\n    function renderRow(row, current, version) {\n        const button = document.createElement('button');\n        button.className = 'queue-item';\n        if (row.index === current)\n            button.classList.add('current');\n        const cover = document.createElement('img');\n        cover.className = 'queue-item-cover';\n        cover.alt = '';\n        cover.loading = 'lazy';\n        cover.decoding = 'async';\n        cover.onerror = () => { cover.onerror = null; cover.src = fallbackCover; };\n        cover.src = fallbackCover;\n        if (row.coverUrl) {\n            sources.set(cover, row.coverUrl);\n            observer.observe(cover);\n        }\n        const text = document.createElement('span');\n        text.className = 'queue-item-text';\n        const title = document.createElement('span');\n        title.className = 'queue-item-title';\n        title.textContent = row.title;\n        const detail = document.createElement('span');\n        detail.className = 'queue-item-detail';\n        detail.textContent = row.artist + ' · ' + duration(row.duration);\n        if (row.index === current)\n            detail.textContent = labels.current + ' · ' + detail.textContent;\n        text.append(title, detail);\n        button.append(cover, text);\n        button.addEventListener('click', () => select(row, version));\n        return button;\n    }\n    function update(state) {\n        status.textContent = state.shuffleOnQueueEnd ? labels.enabled : labels.disabled;\n        if (!state.queue)\n            return;\n        observer.disconnect();\n        pending = [];\n        const queue = state.queue;\n        list.replaceChildren(...queue.items.map(row => renderRow(row, queue.currentIndex, queue.version)));\n        count.textContent = queue.remaining > 50 ? labels.more.replace('{count}', String(queue.remaining)) : '';\n        if (queue.items.length === 0)\n            count.textContent = labels.empty;\n    }\n    return { update };\n}\nreturn createLocalCastQueueView;\n})()";
export const localCastLyricsSource = "function createLocalCastLyricsView(scroller, presence, parse, noLyrics) {\n    let token = null;\n    let text = '';\n    let lyrics = [];\n    let active = -1;\n    function reset() {\n        active = -1;\n        scroller.style.transition = 'none';\n        scroller.style.transform = 'translateY(0px)';\n        scroller.parentElement.scrollTop = 0;\n        // Flush the layout before restoring transitions so the reset stays immediate.\n        Reflect.get(scroller, 'offsetHeight');\n        scroller.style.transition = '';\n    }\n    function select(nextToken, nextText) {\n        if (token === nextToken && text === nextText)\n            return;\n        token = nextToken;\n        text = nextText;\n        reset();\n        lyrics = parse(text);\n        scroller.replaceChildren(...lyrics.map(line => {\n            const element = document.createElement('div');\n            element.className = 'lyric-line';\n            element.textContent = line.text;\n            return element;\n        }));\n        if (lyrics.length === 0) {\n            const empty = document.createElement('div');\n            empty.className = 'lyrics-empty';\n            empty.textContent = noLyrics;\n            scroller.append(empty);\n        }\n        presence(lyrics.length > 0);\n    }\n    function sync(position) {\n        let index = -1;\n        lyrics.forEach((line, candidate) => {\n            if (position >= line.time)\n                index = candidate;\n        });\n        if (index === active)\n            return;\n        active = index;\n        Array.from(scroller.children).forEach((line, candidate) => line.classList.toggle('active', candidate === active));\n        if (index < 0) {\n            reset();\n            return;\n        }\n        const line = scroller.children[index];\n        const offset = -(line.offsetTop - scroller.parentElement.clientHeight / 2 + line.clientHeight / 2);\n        scroller.style.transform = 'translateY(' + offset + 'px)';\n    }\n    return { select, sync };\n}";
export const localCastThemeSource = "function createLocalCastThemeView(style, initialTheme) {\n    let theme = initialTheme;\n    return {\n        getTheme: () => theme,\n        sync(state) {\n            if (!state.theme || state.theme === theme || typeof state.themeCss !== 'string')\n                return;\n            style.textContent = state.themeCss;\n            theme = state.theme;\n        },\n    };\n}";
export const localCastMetadataSource = "function createLocalCastMetadataView(container, labels, save) {\n    let version = '';\n    let pending = false;\n    let selected = null;\n    function clear() {\n        version = '';\n        selected = null;\n        container.hidden = true;\n        container.replaceChildren();\n    }\n    async function edit(params) {\n        if (pending || !selected)\n            return;\n        params.set('trackId', selected.trackId);\n        pending = true;\n        container.querySelectorAll('input, button').forEach(control => { control.disabled = true; });\n        try {\n            await save(params);\n        }\n        catch {\n            const error = document.createElement('span');\n            error.textContent = labels.error;\n            error.setAttribute('role', 'status');\n            container.append(error);\n        }\n        finally {\n            pending = false;\n            container.querySelectorAll('input, button').forEach(control => { control.disabled = false; });\n            version = '';\n        }\n    }\n    function render() {\n        if (!selected)\n            return;\n        const wasOpen = container.querySelector('details')?.open ?? false;\n        container.hidden = false;\n        const rating = document.createElement('div');\n        rating.className = 'track-rating';\n        const currentRating = selected.rating ?? 0;\n        const caption = document.createElement('span');\n        caption.className = 'rating-caption';\n        caption.textContent = labels.rating + ': ' + (currentRating ? currentRating.toFixed(1) : labels.noRating);\n        const stars = document.createElement('div');\n        stars.className = 'rating-stars';\n        stars.setAttribute('role', 'group');\n        stars.setAttribute('aria-label', labels.rating);\n        for (let i = 1; i <= 5; i++) {\n            const star = document.createElement('div');\n            star.className = 'rating-star';\n            const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');\n            svg.setAttribute('viewBox', '0 0 512 512');\n            svg.setAttribute('aria-hidden', 'true');\n            const shape = document.createElementNS('http://www.w3.org/2000/svg', 'path');\n            shape.setAttribute('d', 'M256 32 325 176 480 198 368 307 394 464 256 390 118 464 144 307 32 198 187 176Z');\n            svg.append(shape);\n            const outline = document.createElement('span');\n            outline.className = 'star-outline';\n            outline.append(svg);\n            if (currentRating >= i - 0.5)\n                outline.style.color = '#FFD700';\n            const fill = document.createElement('span');\n            fill.className = 'star-fill';\n            fill.style.width = Math.max(0, Math.min(100, (currentRating - i + 1) * 100)) + '%';\n            fill.append(svg.cloneNode(true));\n            star.append(outline, fill);\n            for (const value of [i - 0.5, i]) {\n                const button = document.createElement('button');\n                button.type = 'button';\n                button.className = value === i ? 'star-hit star-right' : 'star-hit star-left';\n                button.setAttribute('aria-label', labels.rating + ': ' + value + '/5');\n                button.setAttribute('aria-pressed', String(currentRating === value));\n                button.addEventListener('click', () => { void edit(new URLSearchParams({ action: 'rating', rating: String(currentRating === value ? 0 : value) })); });\n                star.append(button);\n            }\n            stars.append(star);\n        }\n        const clearRating = document.createElement('button');\n        clearRating.type = 'button';\n        clearRating.className = 'rating-clear';\n        clearRating.textContent = '×';\n        clearRating.setAttribute('aria-label', labels.noRating);\n        clearRating.addEventListener('click', () => { void edit(new URLSearchParams({ action: 'rating', rating: '0' })); });\n        stars.append(clearRating);\n        rating.append(caption, stars);\n        const details = document.createElement('details');\n        details.open = wasOpen;\n        const summary = document.createElement('summary');\n        const addIcon = document.createElementNS('http://www.w3.org/2000/svg', 'svg');\n        addIcon.setAttribute('viewBox', '0 0 24 24');\n        addIcon.setAttribute('class', 'tag-add-icon');\n        addIcon.setAttribute('aria-hidden', 'true');\n        const addPath = document.createElementNS('http://www.w3.org/2000/svg', 'path');\n        addPath.setAttribute('d', 'M12 8v8M8 12h8M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0');\n        addPath.setAttribute('fill', 'none');\n        addPath.setAttribute('stroke', 'currentColor');\n        addPath.setAttribute('stroke-width', '1.5');\n        addPath.setAttribute('stroke-linecap', 'round');\n        addIcon.append(addPath);\n        const addText = document.createElement('span');\n        addText.textContent = labels.tags;\n        summary.append(addIcon, addText);\n        const list = document.createElement('div');\n        list.className = 'tag-editor';\n        selected.availableTags.forEach(tag => {\n            const row = document.createElement('label');\n            const checkbox = document.createElement('input');\n            checkbox.type = 'checkbox';\n            checkbox.checked = selected.tagIds.includes(tag.id);\n            checkbox.addEventListener('change', () => { void edit(new URLSearchParams({ action: 'tag', tagId: tag.id, associated: String(checkbox.checked) })); });\n            const name = document.createElement('span');\n            name.textContent = tag.name;\n            row.append(checkbox, name);\n            list.append(row);\n        });\n        details.append(summary, list);\n        const assigned = selected.availableTags.filter(tag => selected.tagIds.includes(tag.id)).map(tag => {\n            const badge = document.createElement('button');\n            badge.type = 'button';\n            badge.className = 'track-tag';\n            badge.textContent = tag.name;\n            badge.addEventListener('click', () => { details.open = true; });\n            // Match the app's opaque tag colours, including shorthand and alpha hex.\n            // Always provide a readable fallback instead of the browser's black button text.\n            badge.style.backgroundColor = '#334155';\n            badge.style.color = '#FFFFFF';\n            let hex = String(tag.color ?? '').trim().replace(/^#/, '');\n            if (/^[\\da-f]{3,4}$/i.test(hex))\n                hex = hex.slice(0, 3).split('').map(char => char + char).join('');\n            if (/^[\\da-f]{6}([\\da-f]{2})?$/i.test(hex)) {\n                hex = hex.slice(0, 6);\n                badge.style.backgroundColor = '#' + hex;\n                const [r, g, b] = [0, 2, 4].map(offset => Number.parseInt(hex.slice(offset, offset + 2), 16));\n                const yiq = (r * 299 + g * 587 + b * 114) / 1000;\n                badge.style.color = yiq > 150\n                    ? '#' + [r, g, b].map(channel => Math.floor(channel * 0.3).toString(16).padStart(2, '0')).join('')\n                    : '#FFFFFF';\n            }\n            return badge;\n        });\n        const badges = document.createElement('div');\n        badges.className = 'assigned-tags';\n        badges.append(...assigned, details);\n        container.replaceChildren(rating, badges);\n    }\n    return {\n        getVersion: () => version,\n        clear,\n        sync(state) {\n            if (state.isStopped || state.handoff || state.activeTrack === null) {\n                clear();\n                return;\n            }\n            if (selected && state.trackId && state.trackId !== selected.trackId)\n                clear();\n            if (pending || !state.trackMetadata || !state.metadataVersion || state.metadataVersion === version)\n                return;\n            selected = state.trackMetadata;\n            version = state.metadataVersion;\n            render();\n        },\n    };\n}";
export const localCastSettingsSource = "// Uses the persisted app setting rather than browser storage, so another client\n// and future casting sessions receive the same choice through the existing poll.\nfunction createLocalCastSettingsView(controls, status, errorLabel, save, visibility) {\n    let sessionId = '';\n    let values = { replayGainEnabled: false, hideRatings: false, hideTags: false };\n    let pending = false;\n    function apply() {\n        for (const key of Object.keys(controls)) {\n            controls[key].checked = values[key];\n            controls[key].disabled = pending || !sessionId;\n        }\n        visibility(values.hideRatings, values.hideTags);\n    }\n    for (const key of Object.keys(controls)) {\n        controls[key].addEventListener('change', () => {\n            if (pending || !sessionId)\n                return;\n            const next = controls[key].checked;\n            pending = true;\n            status.textContent = '';\n            Object.values(controls).forEach(control => { control.disabled = true; });\n            void save(key, next, sessionId).then(value => {\n                values = { ...values, [key]: value };\n            }).catch(() => {\n                status.textContent = errorLabel;\n            }).finally(() => { pending = false; apply(); });\n        });\n    }\n    return {\n        sync(state) {\n            if (pending || !state.localCastSettings)\n                return;\n            const next = state.localCastSettings;\n            if (sessionId === next.sessionId && values.replayGainEnabled === next.replayGainEnabled\n                && values.hideRatings === next.hideRatings && values.hideTags === next.hideTags)\n                return;\n            sessionId = next.sessionId;\n            values = { replayGainEnabled: next.replayGainEnabled, hideRatings: next.hideRatings, hideTags: next.hideTags };\n            apply();\n        },\n    };\n}";
export const localCastLayoutSource = "/** Fit only the artwork to the space left by the real controls and metadata.\n * Observers react to tags/fonts/viewport changes, rather than doing work on every poll.\n */\nfunction createLocalCastLayoutView(column, artwork) {\n    let frame = 0;\n    function fit() {\n        frame = 0;\n        const gap = Number.parseFloat(getComputedStyle(column).rowGap) || 0;\n        const siblings = Array.from(column.children).filter(child => child !== artwork);\n        const remaining = column.clientHeight - siblings.reduce((height, child) => height + child.getBoundingClientRect().height, 0) - gap * siblings.length;\n        const size = Math.floor(Math.max(80, Math.min(320, column.clientWidth, remaining)));\n        const value = size + 'px';\n        if (artwork.style.width !== value) {\n            artwork.style.width = value;\n            artwork.style.height = value;\n        }\n    }\n    function schedule() {\n        if (!frame)\n            frame = requestAnimationFrame(fit);\n    }\n    const observer = new ResizeObserver(schedule);\n    observer.observe(column);\n    for (const child of Array.from(column.children))\n        if (child !== artwork)\n            observer.observe(child);\n    window.addEventListener('resize', schedule);\n    schedule();\n    return { dispose() { observer.disconnect(); window.removeEventListener('resize', schedule); cancelAnimationFrame(frame); } };\n}";
